let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const id = input.documentId;
const title = input.title;
const timestamp = input.timestamp;
const key = input.idempotencyKey;
const vendorStatus = input.vendorStatus ?? 200;
const headers = { "content-type": "application/json" };

function emit(o) {
  console.log(JSON.stringify({
    http: o.http,
    database: o.database ?? { rows: [], transaction: { committed: false, rolledBack: o.rolledBack ?? false } },
    messages: o.messages ?? [],
    outbound: o.outbound ?? [],
    ordering: o.ordering ?? [],
    failures: o.failures ?? [],
    retryability: o.retryability ?? false
  }));
}

const fail = (status, code, extra = {}) => emit({
  http: { status, headers, body: { error: code } },
  failures: [{ code, status }],
  ...extra
});

if (typeof title !== "string" || title.trim() === "" || !id) {
  fail(400, "invalid_request");
} else if (input.replay || input.existing) {
  // Idempotent replay: return the original result, no new side effects.
  const prior = input.existing ?? {};
  const doc = { id: prior.id ?? id, title: prior.title ?? title, createdAt: prior.createdAt ?? timestamp };
  emit({
    http: { status: 200, headers: { ...headers, "idempotent-replay": "true" }, body: doc },
    database: { rows: [doc], transaction: { committed: false, replay: true } },
    ordering: ["replay"]
  });
} else {
  const outbound = [{ service: "vendor", action: "authorize", documentId: id, idempotencyKey: key }];
  const ordering = ["vendor.authorize"];
  let failure = null;
  if (vendorStatus >= 400) {
    failure = vendorStatus;
  } else {
    outbound.push({ service: "vendor", action: "index", documentId: id, title, idempotencyKey: key });
    ordering.push("vendor.index");
  }
  if (failure !== null) {
    const retry = failure === 429 || failure >= 500;
    const status = retry ? 503 : 502;
    emit({
      http: { status, headers, body: { error: "vendor_failure", retryable: retry } },
      rolledBack: true,
      outbound,
      ordering,
      failures: [{ code: "vendor_failure", vendorStatus: failure, status }],
      retryability: retry
    });
  } else {
    const doc = { id, title, createdAt: timestamp };
    ordering.push("database.commit", "message.document.created");
    emit({
      http: { status: 201, headers, body: { id, title, createdAt: timestamp } },
      database: { rows: [doc], transaction: { committed: true } },
      messages: [{ type: "document.created", documentId: id, title, timestamp, idempotencyKey: key }],
      outbound,
      ordering
    });
  }
}

